# ---- gate (generated)
P = {"B": 500}
def holm_demo_seed():
    """Data that passes the gate alone but fails among three look-alikes, under the exact run id / B used for the vectors (so the case demonstrates Holm)."""
    for sd in range(1, 600):
        mk = lambda pid, sd=sd: cand(pid, {"target": {"b": arrays(40, 0.025, 0.15, sd)[0], "c": arrays(40, 0.025, 0.15, sd)[1], "direction": "maximize"}, "guardrails": []})
        solo = G.decide_round("C7", [mk("bp")], {"B": 500})[0]["accepted"]
        trio = [d["accepted"] for d in G.decide_round("C7", [mk("bp"), mk("bq"), mk("br")], {"B": 500})]
        if solo and not any(trio):
            return sd
    raise SystemExit("no Holm demonstration data found")
P = {"B": 500}
seed = holm_demo_seed()
bp = lambda pid: cand(pid, {"target": {"b": arrays(40, 0.025, 0.15, seed)[0], "c": arrays(40, 0.025, 0.15, seed)[1], "direction": "maximize"}, "guardrails": []})
gate_cases = []
def add(name, run_id, cands, params=P): gate_cases.append({"name": name, "run_id": run_id, "params": params, "candidates": cands, "expected": G.decide_round(run_id, cands, params)})
add("clear win and no-op", "C1", [cand("win"), cand("noop", variant(delta=0.0, spread=0.0, seed=2))])
add("guardrail regression", "C2", [cand("g", variant(cost_delta=0.5)), cand("ok", variant(cost_delta=0.01, seed=7))])
add("must-pass and preserved", "C3", [cand("m", variant(broken={0})), cand("p", variant(broken=set(range(5, 25)))), cand("fine", seed=9)])
add("format-varied regression", "C4", [cand("f", variant(), variant(delta=-0.1, spread=0.02, seed=3))])
add("heldout regression", "C5", [cand("h", heldout={"target": {"b": [0.5] * 20, "c": [0.2] * 20, "direction": "maximize"}})])
nh = cand("w"); nh["models"]["main"].pop("heldout"); add("needs heldout", "C6", [nh])
add("holm alone (borderline passes)", "C7", [bp("bp")]); add("holm among three (all fail)", "C7", [bp("bp"), bp("bq"), bp("br")])
add("holm with a clear winner", "C8", [cand("clear"), bp("bp"), bp("bq")])
dm = cand("dom"); dm["summary"] = {"target": 0.1, "cost": 2.0, "latency": 5.0}; dm["archive"] = [{"target": 0.2, "cost": 1.0, "latency": 4.0}]; add("dominated", "C9", [dm])
mm = cand("pm"); mm["models"]["gem"] = {"variants": {"canonical": variant(delta=-0.1, spread=0.02, seed=4), "format_varied": variant(delta=-0.1, spread=0.02, seed=4)}, "heldout": mm["models"]["main"]["heldout"]}; add("per-model", "C10", [mm])
add("holm disabled", "C11", [bp("bp"), bp("bq"), bp("br")], {"B": 500, "holm": False})
dump("selfimprove-gate.json", {"cases": gate_cases, "holm_levels": [{"p": p, "alpha": 0.05, "holm": h, "levels": G.holm_levels(p, 0.05, h)} for p, h in (([0.01, 0.04, 0.03], True), ([0.01, None, 0.03], True), ([0.01, 0.04], False))]})

