pcases = []
for name, cfg, env in (("defaults", None, None), ("base override only", CFG, None), ("stricter production", CFG, "prod"), ("leaner development", CFG, "dev"),
                       ("margins and review rate", {"tiers": {"T0": {"margins": {"default": 0.01, "cost": 0.05}}, "T1": {"review": {"sample_rate": 0.5, "window_h": 24}}}}, None)):
    q = GatePolicy.resolve(cfg, env)
    pcases.append({"name": name, "config": cfg, "environment": env, "fingerprint": q.fingerprint, "diff": q.diff(), "relaxed": len(q.relaxed()),
                   "gate_params": {t: q.gate_params(t) for t in ("T0", "T1", "T2")}, "review": {t: q.review(t) for t in ("T0", "T1", "T2")}, "canary": {t: q.canary_fraction(t) for t in ("T0", "T1", "T2")}})
