import asyncio
from si_world import World, proposal, edit_hint
async def golden():
    w = World(tempfile.mkdtemp(), {(1, 1): proposal(edit_hint("HINT+ verify tool output carefully")), (1, 2): proposal(edit_hint("HINT- skip verification entirely")),
                                   (2, 1): proposal(edit_hint("HINT+ plan the steps ahead of time")), (2, 2): proposal(edit_hint("OVERFIT memorise the examples")), "default": None}, cid="01JCRASHSWEEP000000000000A")
    await w.setup(); s = await w.controller().run(); ev = w.store.events(w.cid)
    out = {"campaign_id": w.cid, "main_head": w.config.head(), "stopped": s["stopped"], "events": [{"seq": e["seq"], "type": e["type"], "hash": e["hash"]} for e in ev]}; w.close(); return out
dump("selfimprove-campaign.json", asyncio.run(golden()))
print("wrote", sorted(p.name for p in OUT.glob("selfimprove-*")))
